"use client";

import type { ReactNode } from "react";
import { useCurrentFrame, useVideoConfig } from "remotion";

export type WebcamBubbleShape = "circle" | "rounded";

export type WebcamBubbleCorner =
  | "bottom-right"
  | "bottom-left"
  | "top-right"
  | "top-left";

export interface WebcamBubbleKeyframe {
  /** Frame at which this reposition/resize starts. */
  frame: number;
  /** New corner to travel to. Omit to keep the current corner. */
  corner?: WebcamBubbleCorner;
  /** New diameter in px. Omit to keep the current size. */
  size?: number;
}

export interface WebcamBubbleProps {
  /**
   * Your facecam media — a Remotion `<Video>`, `<OffthreadVideo>` or `<Img>`.
   * Style it with `width/height: "100%"` and `objectFit: "cover"` so it fills
   * the clipped frame. When omitted, a deterministic founder placeholder is
   * rendered so the bubble previews without an asset.
   */
  children?: ReactNode;
  /** Circular bubble or a rounded-corner square. */
  shape?: WebcamBubbleShape;
  /** Which corner of the composition the bubble docks to. */
  corner?: WebcamBubbleCorner;
  /** Bubble diameter (px). Also the square edge for `shape="rounded"`. */
  size?: number;
  /** Gap (px) between the bubble and the composition edges. */
  inset?: number;
  borderWidth?: number;
  borderColor?: string;
  /** CSS box-shadow under the bubble. */
  shadow?: string;
  /**
   * Scripted repositions/resizes. Each keyframe starts animating at its
   * `frame` and settles over `transitionFrames`. Space keyframes at least
   * `transitionFrames` apart.
   */
  keyframes?: WebcamBubbleKeyframe[];
  /** Frames one keyframe move takes to settle. */
  transitionFrames?: number;
  /** Frame at which the 10f scale-fade entrance starts. */
  enterAtFrame?: number;
  /** Frame at which the 10f scale-fade exit starts. Omit to never exit. */
  exitAtFrame?: number;
  /** Tint of the built-in placeholder facecam (used only without children). */
  placeholderColor?: string;
  speed?: number;
  className?: string;
}

/** Duration (frames) of the enter/exit scale-fade. */
export const ENTER_EXIT_FRAMES = 10;

/** Corner radius of the `rounded` shape, as a fraction of the bubble size. */
export const ROUNDED_RADIUS_RATIO = 0.14;

const clamp01 = (t: number) => Math.min(1, Math.max(0, t));

/** Standard ease-out cubic, for the entrance/exit. */
export function easeOutCubic(t: number): number {
  const c = clamp01(t);
  return 1 - (1 - c) ** 3;
}

/** Symmetric ease-in-out cubic, for keyframe travel. */
export function easeInOutCubic(t: number): number {
  const c = clamp01(t);
  return c < 0.5 ? 4 * c * c * c : 1 - (-2 * c + 2) ** 3 / 2;
}

/** Top-left position of a bubble docked at `corner` inside a width×height scene. */
export function cornerPosition(
  corner: WebcamBubbleCorner,
  size: number,
  inset: number,
  width: number,
  height: number,
): { x: number; y: number } {
  const x = corner.endsWith("right") ? width - inset - size : inset;
  const y = corner.startsWith("bottom") ? height - inset - size : inset;
  return { x, y };
}

/** Keyframes sorted by frame, invalid (negative-size) entries dropped. */
export function normalizeKeyframes(
  keyframes: WebcamBubbleKeyframe[],
): WebcamBubbleKeyframe[] {
  return keyframes
    .filter((k) => k.size === undefined || k.size > 0)
    .slice()
    .sort((a, b) => a.frame - b.frame);
}

export interface BubblePlacement {
  /** Top-left x of the bubble. */
  x: number;
  /** Top-left y of the bubble. */
  y: number;
  /** Current diameter. */
  size: number;
}

export interface ResolvePlacementOptions {
  corner: WebcamBubbleCorner;
  size: number;
  inset: number;
  width: number;
  height: number;
  keyframes?: WebcamBubbleKeyframe[];
  transitionFrames?: number;
}

/**
 * Pure layout resolver: walks the keyframe schedule and returns the bubble's
 * top-left position and size at `frame`. Mid-transition, size is eased first
 * and corner anchors are re-derived from the eased size, so the bubble stays
 * flush to its inset at both ends of a move.
 */
export function resolveBubblePlacement(
  frame: number,
  options: ResolvePlacementOptions,
): BubblePlacement {
  const {
    corner,
    size,
    inset,
    width,
    height,
    keyframes = [],
    transitionFrames = 18,
  } = options;
  const T = Math.max(1, transitionFrames);

  let currentCorner = corner;
  let currentSize = size;

  for (const kf of normalizeKeyframes(keyframes)) {
    const targetCorner = kf.corner ?? currentCorner;
    const targetSize = kf.size ?? currentSize;
    if (frame >= kf.frame + T) {
      // Move fully settled — adopt and keep walking.
      currentCorner = targetCorner;
      currentSize = targetSize;
      continue;
    }
    if (frame >= kf.frame) {
      // Mid-transition.
      const p = easeInOutCubic((frame - kf.frame) / T);
      const easedSize = currentSize + (targetSize - currentSize) * p;
      const from = cornerPosition(
        currentCorner,
        easedSize,
        inset,
        width,
        height,
      );
      const to = cornerPosition(targetCorner, easedSize, inset, width, height);
      return {
        x: from.x + (to.x - from.x) * p,
        y: from.y + (to.y - from.y) * p,
        size: easedSize,
      };
    }
    // This keyframe (and all later ones) hasn't started yet.
    break;
  }

  const pos = cornerPosition(currentCorner, currentSize, inset, width, height);
  return { x: pos.x, y: pos.y, size: currentSize };
}

export interface EnterExitState {
  opacity: number;
  scale: number;
}

/**
 * Pure enter/exit schedule: a 10-frame ease-out scale-fade in at
 * `enterAtFrame`, and (when set) a 10-frame scale-fade out at `exitAtFrame`.
 */
export function enterExitState(
  frame: number,
  enterAtFrame: number,
  exitAtFrame?: number,
): EnterExitState {
  const enter = easeOutCubic((frame - enterAtFrame) / ENTER_EXIT_FRAMES);
  let opacity = enter;
  let scale = 0.8 + 0.2 * enter;
  if (exitAtFrame !== undefined && frame >= exitAtFrame) {
    const exit = easeOutCubic((frame - exitAtFrame) / ENTER_EXIT_FRAMES);
    opacity *= 1 - exit;
    scale *= 1 - 0.12 * exit;
  }
  return { opacity, scale };
}

/**
 * Deterministic stand-in facecam: a tinted gradient with a founder silhouette
 * that bobs gently, so the bubble reads as "camera" before real footage lands.
 */
function PlaceholderFacecam({
  frame,
  color,
}: {
  frame: number;
  color: string;
}) {
  const bob = Math.sin(frame / 14) * 2.5;
  const sway = Math.cos(frame / 22) * 1.5;
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: `linear-gradient(160deg, ${color} -20%, #101828 130%)`,
      }}
    >
      <svg
        viewBox="0 0 100 100"
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          translate: `${sway}px ${bob}px`,
        }}
        aria-hidden
      >
        {/* Head */}
        <circle cx="50" cy="42" r="16" fill="rgba(255,255,255,0.92)" />
        {/* Shoulders */}
        <path
          d="M 18 104 C 18 78 32 66 50 66 C 68 66 82 78 82 104 Z"
          fill="rgba(255,255,255,0.92)"
        />
      </svg>
    </div>
  );
}

export function WebcamBubble({
  children,
  shape = "circle",
  corner = "bottom-right",
  size = 220,
  inset = 48,
  borderWidth = 3,
  borderColor = "#FFFFFF",
  shadow = "0 8px 24px rgba(16,24,40,0.18)",
  keyframes,
  transitionFrames = 18,
  enterAtFrame = 0,
  exitAtFrame,
  placeholderColor = "#266DF0",
  speed = 1,
  className,
}: WebcamBubbleProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();

  const placement = resolveBubblePlacement(frame, {
    corner,
    size,
    inset,
    width,
    height,
    keyframes,
    transitionFrames,
  });
  const life = enterExitState(frame, enterAtFrame, exitAtFrame);

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
    >
      <div
        style={{
          position: "absolute",
          left: placement.x,
          top: placement.y,
          width: placement.size,
          height: placement.size,
          borderRadius:
            shape === "circle"
              ? "50%"
              : Math.round(placement.size * ROUNDED_RADIUS_RATIO),
          border: `${borderWidth}px solid ${borderColor}`,
          boxShadow: shadow,
          backgroundColor: "#141417",
          overflow: "hidden",
          opacity: life.opacity,
          scale: String(life.scale),
          transformOrigin: "center",
        }}
      >
        {children ?? (
          <PlaceholderFacecam frame={frame} color={placeholderColor} />
        )}
      </div>
    </div>
  );
}
